const axios = require('axios');

const base64Audio = $json.base64Audio;
const mimeType = $json.mimeType;

const fechaHoyAR = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' });

const categoriasGasto = ['Supermercado', 'Delivery/Restaurantes', 'Transporte/Nafta', 'Servicios', 'Alquiler', 'Salud', 'Ocio', 'Ropa', 'Educación', 'Suscripciones', 'Impuestos', 'Otros'];
const categoriasIngreso = ['Clientes', 'Sueldo', 'Ventas', 'Otros'];

const prompt = `Sos un extractor de movimientos financieros a partir de audio en español rioplatense (Argentina).
Fecha de hoy: ${fechaHoyAR} (timezone America/Argentina/Buenos_Aires). Resolvé fechas relativas ("ayer", "el viernes pasado") contra esta fecha, nunca uses UTC.

Un audio puede contener uno o varios movimientos (gasto o ingreso). Devolvé SIEMPRE un array, uno por movimiento. Si el audio no contiene ningún movimiento financiero, devolvé un array vacío [].

Reglas de argot monetario argentino:
- "20 lucas" = 20000
- "2 palos" = 2000000
- "500 mangos" = 500
- "un verde" = 1 USD (y en general "verdes" = dólares)

Categorías válidas para tipo=gasto: ${categoriasGasto.join(', ')}
Categorías válidas para tipo=ingreso: ${categoriasIngreso.join(', ')}

Si NO podés determinar el monto con confianza razonable, poné confianza "baja" y NO inventes un número (poné monto en 0).
Guardá siempre en transcripcion_raw una transcripción fiel de lo que se dijo.`;

const responseSchema = {
  type: 'ARRAY',
  items: {
    type: 'OBJECT',
    properties: {
      tipo: { type: 'STRING', enum: ['gasto', 'ingreso'] },
      monto: { type: 'NUMBER' },
      moneda: { type: 'STRING', enum: ['ARS', 'USD'] },
      descripcion: { type: 'STRING' },
      comercio: { type: 'STRING', nullable: true },
      categoria: { type: 'STRING' },
      metodo_pago: { type: 'STRING', enum: ['efectivo', 'debito', 'credito', 'transferencia', 'mercadopago'], nullable: true },
      cuotas: { type: 'INTEGER' },
      fecha: { type: 'STRING' },
      confianza: { type: 'STRING', enum: ['alta', 'media', 'baja'] },
      transcripcion_raw: { type: 'STRING' }
    },
    required: ['tipo', 'monto', 'moneda', 'descripcion', 'categoria', 'cuotas', 'fecha', 'confianza', 'transcripcion_raw']
  }
};

let movimientos;
try {
  const { data } = await axios.post(
    'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent',
    {
      contents: [{
        parts: [
          { text: prompt },
          { inlineData: { mimeType, data: base64Audio } }
        ]
      }],
      generationConfig: {
        responseMimeType: 'application/json',
        responseSchema
      }
    },
    {
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': process.env.GEMINI_API_KEY
      },
      timeout: 30000
    }
  );

  const textoRespuesta = data.candidates[0].content.parts[0].text;
  movimientos = JSON.parse(textoRespuesta);
} catch (error) {
  throw new Error(`Gemini falló: ${error.message}`);
}

return movimientos.map((m) => ({ json: m }));

const axios = require('axios');
const item = $json;

const SUPABASE_URL = process.env.SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

const supabaseHeaders = {
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  'Content-Type': 'application/json'
};

let categoriaId = null;
let categoriaEmoji = '📦';
let categoriaNombre = item.categoria;

try {
  const { data: categorias } = await axios.get(`${SUPABASE_URL}/rest/v1/categorias`, {
    headers: supabaseHeaders,
    params: { nombre: `eq.${item.categoria}`, tipo: `eq.${item.tipo}`, select: 'id,emoji,nombre' }
  });
  if (categorias.length > 0) {
    categoriaId = categorias[0].id;
    categoriaEmoji = categorias[0].emoji;
    categoriaNombre = categorias[0].nombre;
  }
} catch (error) {
  throw new Error(`No pude buscar la categoría en Supabase: ${error.message}`);
}

let tcUsado = null;
try {
  const { data: tcRows } = await axios.get(`${SUPABASE_URL}/rest/v1/tipo_cambio`, {
    headers: supabaseHeaders,
    params: { select: 'oficial_venta', order: 'fecha.desc', limit: 1 }
  });
  if (tcRows.length > 0) tcUsado = tcRows[0].oficial_venta;
} catch (error) {
  tcUsado = null;
}

let montoArs;
let montoUsd;
if (item.moneda === 'ARS') {
  montoArs = item.monto;
  montoUsd = tcUsado ? Number((item.monto / tcUsado).toFixed(2)) : null;
} else {
  montoUsd = item.monto;
  montoArs = tcUsado ? Number((item.monto * tcUsado).toFixed(2)) : item.monto;
}

const payload = {
  tipo: item.tipo,
  fecha: item.fecha,
  monto_ars: montoArs,
  monto_usd: montoUsd,
  tc_usado: tcUsado,
  moneda_origen: item.moneda,
  categoria_id: categoriaId,
  comercio: item.comercio || null,
  descripcion: item.descripcion,
  metodo_pago: item.metodo_pago || null,
  cuotas_total: 1,
  cuota_nro: 1,
  fuente: 'audio',
  transcripcion_raw: item.transcripcion_raw,
  confianza: item.confianza
};

let inserted;
try {
  const { data } = await axios.post(`${SUPABASE_URL}/rest/v1/movimientos`, payload, {
    headers: { ...supabaseHeaders, Prefer: 'return=representation' }
  });
  inserted = data[0];
} catch (error) {
  throw new Error(`No pude insertar el movimiento en Supabase: ${error.message}`);
}

return [{
  json: {
    ...inserted,
    categoriaEmoji,
    categoriaNombre
  }
}];
